import java.util.ResourceBundle;
import javax.enterprise.context.RequestScoped;
import javax.inject.Inject;
import javax.inject.Named;
import jakarta.mvc.MvcContext;
//https://www.mvc-spec.org/learn/cookbook/multilang_en.html
/**
 * Provides I18n messages for the UI per request. To get the correct locale, the method {@link MvcContext#getLocale()}
 * is used. This method uses the built-in {@link jakarta.mvc.locale.LocaleResolver} of the used MVC Implementation.
 *
 * @author Tobias Erdle
 * @see MvcContext#getLocale()
 * @see jakarta.mvc.locale.LocaleResolver
 */
@RequestScoped
@Named("msg")
public class Messages {

    private static final String BASE_NAME = "messages";

    @Inject
    private MvcContext mvcContext;

    /**
     * Get the assigned message to some key based on the {@link java.util.Locale} of the current request.
     *
     * @param key the message key to use
     * @return the correct translation assigned to the key for the request locale, a fallback translation or a
     * placeholder for unknown keys.
     */
    public final String get(final String key) {
        final ResourceBundle bundle = ResourceBundle.getBundle(BASE_NAME, mvcContext.getLocale());

        return bundle.containsKey(key) ? bundle.getString(key) : formatUnknownKey(key);
    }

    private static String formatUnknownKey(final String key) {
        return String.format("???%s???", key);
    }
}

package com.example.web;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Named;
import jakarta.mvc.RedirectScoped;

/**
 * Used to transport messages back to the client.
 *
 * @author Hantsy Bai<hantsy@gmail.com>
 */
@RedirectScoped
@Named("flashMessage")
public class AlertMessage implements Serializable {

    private static final long serialVersionUID = 1L;

    public enum Type {
        success, warning, danger, info;
    }

    private Type type = Type.info;
    private String text;
    private String code;

    public AlertMessage() {
    }

    public AlertMessage(Type type, String text) {
        this.type = type;
        this.text = text;
    }

    public AlertMessage(Type type, String code, String message) {
        this.type = type;
        this.code = code;
        this.text = message;
    }

    public String getText() {
        return text;
    }

    public Type getType() {
        return type;
    }

    public String getCode() {
        return code;
    }

    public void notify(Type type, String text) {
        this.type = type;
        this.text = text;
    }

    public static AlertMessage success(String text) {
        return new AlertMessage(Type.success, text);
    }

    public static AlertMessage warning(String text) {
        return new AlertMessage(Type.warning, text);
    }

    public static AlertMessage danger(String text) {
        return new AlertMessage(Type.danger, text);
    }

    public static AlertMessage info(String text) {
        return new AlertMessage(Type.info, text);
    }

    private List<Error> errors = new ArrayList<>();

    public List<Error> getErrors() {
        return errors;
    }

    public void setErrors(List<Error> errors) {
        this.errors = errors;
    }

    public void addError(String field, String code, String message) {
        this.errors.add(new Error(field, code, message));
    }

    public static class Error {

        private String code;
        private String message;
        private String field;

        public Error(){}

        private Error(String field, String code, String message) {
            this.field = field;
            this.code = code;
            this.message = message;
        }

        public String getCode() {
            return code;
        }

        public void setCode(String code) {
            this.code = code;
        }

        public String getMessage() {
            return message;
        }

        public void setMessage(String message) {
            this.message = message;
        }

        public String getField() {
            return field;
        }

        public void setField(String field) {
            this.field = field;
        }

    }

}

